<script setup lang="ts">
import {computed} from 'vue';
type Node={path:string;name:string;children?:Node[]};
const props=defineProps<{files:string[];selected:string;expanded:string[];nodes?:Node[];depth?:number}>();
const emit=defineEmits<{select:[path:string];toggle:[path:string]}>();
const tree=computed(()=>{if(props.nodes)return props.nodes;const root:Node[]=[];for(const path of props.files){const parts=path.split('/');let parent=root;let current='';for(let i=0;i<parts.length;i++){current+=(i?'/':'')+parts[i];let node=parent.find(n=>n.path===current);if(!node){node={path:current,name:parts[i],...(i<parts.length-1?{children:[]}: {})};parent.push(node);}parent=node.children||[];}}return root.sort((a,b)=>a.name==='.env'?-1:b.name==='.env'?1:a.children&&!b.children?-1:!a.children&&b.children?1:0);});
</script>
<template><ul class="project-tree" :role="depth?'group':'tree'" aria-label="项目文件"><li v-for="node in tree" :key="node.path" role="none"><button type="button" role="treeitem" :aria-selected="!node.children&&selected===node.path" :aria-expanded="node.children?expanded.includes(node.path):undefined" :aria-label="node.children?`${expanded.includes(node.path)?'收起':'展开'} ${node.name} 文件夹`:node.path" :data-file="node.children?undefined:node.path" :data-folder="node.children?node.path:undefined" :class="{selected:selected===node.path,folder:node.children}" :style="{paddingLeft:8+(depth||0)*14+'px'}" @click="node.children?emit('toggle',node.path):emit('select',node.path)" @keydown.right.prevent="node.children&&!expanded.includes(node.path)&&emit('toggle',node.path)" @keydown.left.prevent="node.children&&expanded.includes(node.path)&&emit('toggle',node.path)"><svg class="tree-chevron" :class="{open:expanded.includes(node.path),empty:!node.children}" viewBox="0 0 12 12" aria-hidden="true"><path d="m4 2 4 4-4 4"/></svg><svg v-if="node.children" class="folder-icon" viewBox="0 0 24 20" aria-hidden="true"><path d="M1 4a2 2 0 0 1 2-2h6l2 2h10a2 2 0 0 1 2 2v10a2 2 0 0 1-2 2H3a2 2 0 0 1-2-2z" fill="#6bb6df"/><path d="M1 6h22v10a2 2 0 0 1-2 2H3a2 2 0 0 1-2-2z" fill="#8bcaec"/><path d="M2 7h20" stroke="#b5e1f8"/></svg><svg v-else class="document-icon" :class="{'python-file':node.name.endsWith('.py'),'env-file':node.name==='.env'}" viewBox="0 0 20 24" aria-hidden="true"><path d="M3 1h9l5 5v16H3z" fill="currentColor" fill-opacity=".06" stroke="currentColor" stroke-width="1"/><path d="M12 1v5h5M6 11h8M6 15h7" fill="none" stroke="currentColor" stroke-width="1"/></svg><span class="node-label" :title="node.name">{{node.name}}</span></button><ProjectTree v-if="node.children&&expanded.includes(node.path)" :files="files" :nodes="node.children" :selected="selected" :expanded="expanded" :depth="(depth||0)+1" @select="emit('select',$event)" @toggle="emit('toggle',$event)"/></li></ul></template>
<style scoped>
.project-tree{list-style:none;padding:0!important;margin:0!important}.project-tree li{list-style:none;margin:0!important}.project-tree button{display:flex;align-items:center;gap:7px;width:100%;height:30px;border-radius:5px;text-align:left;color:var(--vp-c-text-2);font:12px var(--vp-font-family-base);padding-right:8px;overflow:hidden;outline:none}.project-tree button:hover{background:#00000005}.project-tree button.selected{background:#e5eff8;color:#245472}.project-tree button:focus-visible{box-shadow:inset 0 0 0 1px #a3c9e0}.tree-chevron{width:10px;height:10px;flex:none;stroke:#8a9099;stroke-width:1.4;fill:none;transition:transform .12s}.tree-chevron.open{transform:rotate(90deg)}.tree-chevron.empty{visibility:hidden}.folder-icon{width:19px;height:17px;flex:none}.document-icon{width:16px;height:19px;color:#9a9faa;flex:none}.python-file{color:#6795b9}.env-file{color:#849987}.node-label{overflow:hidden;text-overflow:ellipsis;white-space:nowrap;line-height:1.4}.folder .node-label{font-weight:550}.dark .project-tree button.selected{background:#263746;color:#b0d4ec}.dark .project-tree button:hover{background:#ffffff07}
</style>
